interface Pesanan {
  readonly id: number;
  menu: string;
  catatan?: string;
}
const daftar: Pesanan[] = [
  { id: 1, menu: "Kopi" },
  { id: 2, menu: "Teh", catatan: "kurang manis" },
];
for (const p of daftar) {
  console.log(`#${p.id} ${p.menu} (${p.catatan ?? "tanpa catatan"})`);
}
console.log(daftar[0].catatan?.length);

