cards.solution:
interface Akun {
  readonly id: number;
  nama: string;
  bio?: string;
}
const akun: Akun[] = [
  { id: 1, nama: "Rina", bio: "Suka kopi" },
  { id: 2, nama: "Budi" },
];
for (const a of akun) {
  console.log(`${a.id}-${a.nama}: ${a.bio ?? "(belum diisi)"}`);
}
